  cutoff:['Filter cutoff',30,16000,1,'Hz'],resonance:['Resonance',.5,12,.1,''],filterEnv:['Filter envelope',0,5,.01,'oct'],vowel:['Vowel position',0,1,.01,''],vowelMix:['Vowel mix',0,1,.01,''],combMix:['Comb mix',0,1,.01,''],combFreq:['Comb frequency',30,2000,1,'Hz'],combFeedback:['Comb feedback',0,.85,.01,''],
  dispersion:['Dispersion mix',0,1,.01,''],dispersionFreq:['Dispersion frequency',40,4000,1,'Hz'],dispersionPinch:['Dispersion focus',0,1,.01,''],
  lowDrive:['Low-band drive',0,1,.01,''],midDrive:['Mid-band drive',0,1,.01,''],highDrive:['High-band drive',0,1,.01,''],distortionMix:['Parallel distortion',0,1,.01,''],crossover:['Character low cut',40,240,1,'Hz'],highCross:['High crossover',600,6000,1,'Hz'],preHP:['Pre-drive high pass',20,1200,1,'Hz'],postLP:['Post-drive low pass',500,18000,1,'Hz'],compression:['Multiband dynamics',0,1,.01,''],
