  const tone=selectField('filterType','Main filter',[['lowpass','Low pass'],['bandpass','Band pass'],['highpass','High pass'],['notch','Notch']])+['cutoff','resonance','filterEnv'].map(field).join('')+group('VOWEL / A → E → I → O → U')+['vowel','vowelMix'].map(field).join('')+group('COMB RESONATOR')+['combMix','combFreq','combFeedback'].map(field).join('')+group('ALL-PASS DISPERSION')+['dispersion','dispersionFreq','dispersionPinch'].map(field).join('');
