  $('#bassPages').innerHTML=`<div class="bass-page" data-page="voice"><div class="bass-grid">${voice}</div></div><div class="bass-page" data-page="tone"><div class="bass-grid">${tone}</div></div><div class="bass-page" data-page="fx"><div class="bass-grid">${fx}</div><div id="fxOrder" class="fx-order"></div></div><div class="bass-page" data-page="phrase"><div class="phrase-tools">${checkField('seqEnabled','Phrase enabled')}<label>GRID <select id="phraseDivision"><option value="2">1/8</option><option value="4">1/16</option><option value="3">1/8 triplet</option><option value="6">1/16 triplet</option></select></label><button id="phraseShift">Shift →</button><button id="phraseVariation">Variation</button><button id="phraseClear">Clear</button></div><div class="bass-control">${field('swing')}</div><div class="phrase-grid" id="phraseGrid"></div><div class="step-detail" id="stepDetail"></div><p class="bass-description">Select a step to edit note, velocity, gate, retriggers and timbre locks. Enable its square to trigger it. Press Play in the global display.</p></div><div class="bass-page" data-page="sample"><div class="resample-actions"><button class="bass-action" id="capturePhrase">Capture phrase</button><label>Length <select id="captureBars"><option value="1">1 bar</option><option value="2">2 bars</option></select></label>${checkField('captureSub','Include sub')}<button class="bass-action" id="exportSample">Export WAV</button><label>Import audio <input class="file-input" id="sampleImport" type="file" accept="audio/*"></label><span class="capture-state" id="captureState">${p.sample?'CAPTURE READY':'NO CAPTURE'}</span></div><canvas class="sample-wave" id="sampleWave"></canvas><div class="bass-grid">${['sampleStart','sampleEnd','sampleStretch','sampleBlend'].map(field).join('')}${checkField('sampleReverse','Reverse region')}</div><p class="bass-description">Captures up to 8 seconds. Audio is stored inside saved patches. Character-only capture preserves the independent sub. Time stretch changes grain travel independently of note pitch.</p></div>`;
