  $('#captureBars').value=p.captureBars;$('#captureBars').onchange=e=>{p.captureBars=+e.target.value;changedBass()};$('#capturePhrase').onclick=capturePhrase;$('#exportSample').onclick=exportSample;$('#sampleImport').onchange=importSample;
