// Extend the original matrix with actual bass destinations and per-route shaping.
renderRoutes=function(){
  const sources=sel=>state.gens.map((g,i)=>`<option value="${i}" ${i===sel?'selected':''}>${g.name}</option>`).join('');
  const targets=[...state.gens.flatMap((g,i)=>definitions[types.indexOf(g.type)].map((n,j)=>[`gen:${i}:${j}`,`${g.name} · ${n}`])),...['fm','ratio','feedback','warp','cutoff','vowel','vowelMix','combFreq','combMix','dispersion','dispersionFreq','drive','distortionMix','delayMix','pitch','amp','pan'].map(k=>[k,'Bass · '+(rangeSpec[k]?.[0]||k)])];
  $('#routes').innerHTML=state.routes.map((r,i)=>`<div class="route"><select data-new-route="${i}" data-route-key="from" aria-label="Route ${i+1} source">${sources(r.from)}</select><span>→</span><select class="target-select" data-new-route="${i}" data-route-key="target" aria-label="Route ${i+1} target">${targets.map(([key,label])=>`<option value="${key}" ${(r.target||`gen:${r.to}:0`)===key?'selected':''}>${label}</option>`).join('')}</select><label>Depth <output>${r.depth}%</output><input aria-label="Route ${i+1} depth" data-new-route="${i}" data-route-key="depth" type="range" min="-100" max="100" value="${r.depth}"></label><label>Lag <input aria-label="Route ${i+1} lag" data-new-route="${i}" data-route-key="lag" type="range" min="0" max="100" value="${r.lag}"></label><select class="route-curve" data-new-route="${i}" data-route-key="curve" aria-label="Route ${i+1} curve">${['linear','exponential','stepped'].map(v=>`<option ${v===(r.curve||'linear')?'selected':''}>${v}</option>`).join('')}</select><label><input type="checkbox" data-new-route="${i}" data-route-key="bipolar" ${r.bipolar?'checked':''}>Bipolar</label><label><input type="checkbox" data-new-route="${i}" data-route-key="invert" ${r.invert?'checked':''}>Invert</label><button data-delete-route="${i}" aria-label="Remove route ${i+1}">×</button></div>`).join('');
  $$('[data-new-route]').forEach(el=>el.oninput=()=>{const r=state.routes[+el.dataset.newRoute],key=el.dataset.routeKey;r[key]=el.type==='checkbox'?el.checked:['target','curve'].includes(key)?el.value:+el.value;if(key==='depth')el.previousElementSibling.textContent=el.value+'%';changedBass()});$$('[data-delete-route]').forEach(b=>b.onclick=()=>{state.routes.splice(+b.dataset.deleteRoute,1);renderRoutes();changedBass()});
};
const bassBaseRender=render;render=function(){state.bass={...bankSettings(state.preset),...state.bass};bassBaseRender();renderBass()};
const bassBaseLoad=loadPreset;loadPreset=function(i){state.bass=bankSettings((i+4)%4);sentSampleId=null;sampleCache=null;bassBaseLoad(i);cleanSignature=patchSignature();updatePatchIdentity();renderBass()};
function syncAudio(){if(syncScheduled)return;syncScheduled=true;requestAnimationFrame(()=>{syncScheduled=false;if(!bassNode)return;const bass={...state.bass,sample:state.bass.sample?{id:state.bass.sample.id,root:state.bass.sample.root,rate:state.bass.sample.rate}:null},patch={bass,bpm:state.bpm,sync:state.sync,volume:state.volume,softclip:state.softclip,macros:state.macros,gens:state.gens,routes:state.routes};const serialized=JSON.stringify(patch);if(serialized!==lastConfig){bassNode.port.postMessage({type:'patch',patch});lastConfig=serialized;}if(state.bass.sample?.id!==sentSampleId){sentSampleId=state.bass.sample?.id;if(state.bass.sample){sampleCache=decodeSample(state.bass.sample);bassNode.port.postMessage({type:'sample',samples:sampleCache,rate:state.bass.sample.rate});drawSample()}else{sampleCache=null;bassNode.port.postMessage({type:'sample',samples:null,rate:22050})}}})}
document.addEventListener('input',syncAudio);document.addEventListener('change',syncAudio);document.addEventListener('click',syncAudio);
async function ensureAudio(){
  if(bassContext){await bassContext.resume();return;}
  if(bootPromise)return bootPromise;
  bootPromise=(async()=>{
    bassContext=new AudioContext({latencyHint:'interactive'});await bassContext.audioWorklet.addModule('bass-worklet.js');
    bassNode=new AudioWorkletNode(bassContext,'motherbox-bass',{numberOfInputs:0,numberOfOutputs:3,outputChannelCount:[2,1,2]});
    analyser=bassContext.createAnalyser();analyser.fftSize=2048;analyser.smoothingTimeConstant=.7;bassNode.connect(analyser,0);analyser.connect(bassContext.destination);
    analyserSub=bassContext.createAnalyser();analyserSub.fftSize=1024;bassNode.connect(analyserSub,1);
    const splitter=bassContext.createChannelSplitter(2);bassNode.connect(splitter,0);leftAnalyser=bassContext.createAnalyser();rightAnalyser=bassContext.createAnalyser();leftAnalyser.fftSize=rightAnalyser.fftSize=1024;splitter.connect(leftAnalyser,0);splitter.connect(rightAnalyser,1);
    frequencyData=new Float32Array(analyser.frequencyBinCount);timeData=new Float32Array(analyser.fftSize);subData=new Float32Array(1024);leftData=new Float32Array(1024);rightData=new Float32Array(1024);
    bassNode.port.onmessage=({data:d})=>{if(d.type==='status'){latestStatus=d;d.outputs.forEach((v,i)=>outputs[i]=v);$$('[data-step-cell]').forEach(c=>c.classList.toggle('playing',transportOn&&+c.dataset.stepCell===d.step));}if(d.type==='capture'){storeCaptured(d.samples,d.rate,d.root);if(autoCaptureTransport){setTransport(false);autoCaptureTransport=false;}}};
    $('#engineStatus').textContent='AUDIOWORKLET · '+Math.round(bassContext.sampleRate/1000)+' kHz';await bassContext.resume();lastConfig='';syncAudio();
  })().catch(e=>{bassContext?.close();bassContext=null;bootPromise=null;$('#engineStatus').textContent='AUDIO UNAVAILABLE';throw e});return bootPromise;
}
async function setTransport(on){try{await ensureAudio();transportOn=on;running=on||heldKeys.size>0;bassNode.port.postMessage({type:'transport',on});$('#play').textContent=on?'Ⅱ':'▶';$('#play').setAttribute('aria-label',on?'Stop audio':'Start audio');$('#audioStatus').textContent=on?'LIVE':'READY';}catch(e){toast('Audio could not start: '+e.message)}}
$('#play').onclick=()=>setTransport(!transportOn);
// The previous preview synth is replaced, including its master-volume handler.
updateVolume=function(){$('#db').textContent=Math.round(20*Math.log10(Math.max(.001,+$('#volume').value/100*.75)))+' dB';syncAudio()};$('#volume').oninput=updateVolume;updateVolume();
async function playNote(note,velocity,id){try{await ensureAudio();heldKeys.add(id);running=true;bassNode.port.postMessage({type:'noteOn',note,velocity,id});$('#liveNote').textContent=noteName(note);$('#audioStatus').textContent='LIVE';}catch(e){toast('Audio could not start: '+e.message)}}
function releaseNote(id){heldKeys.delete(id);bassNode?.port.postMessage({type:'noteOff',id});running=transportOn||heldKeys.size>0;}
$('#panic').onclick=()=>{heldKeys.clear();$$('.piano button').forEach(b=>b.classList.remove('held'));bassNode?.port.postMessage({type:'panic'});transportOn=running=false;$('#play').textContent='▶';$('#play').setAttribute('aria-label','Start audio');$('#audioStatus').textContent='READY';$('#liveNote').textContent='NO NOTE'};
const keyMap={a:0,w:1,s:2,e:3,d:4,f:5,t:6,g:7,y:8,h:9,u:10,j:11,k:12};
function renderKeyboard(){const black=[1,3,6,8,10];$('#piano').innerHTML=Object.entries(keyMap).map(([key,offset])=>`<button class="${black.includes(offset)?'black':''}" data-piano="${offset}" aria-label="Play ${noteName(keyboardBase+offset)}">${key.toUpperCase()}</button>`).join('');$$('[data-piano]').forEach(b=>{const id='pointer-'+b.dataset.piano;b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);b.classList.add('held');playNote(keyboardBase + +b.dataset.piano,.85,id)};b.onpointerup=b.onpointercancel=()=>{b.classList.remove('held');releaseNote(id)}});$('#keyboardOctave').textContent=noteName(keyboardBase)}
document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||$('#saveDialog').open||$('#helpDialog').open)return;const key=e.key.toLowerCase();if(e.repeat)return;if(key===' '){e.preventDefault();setTransport(!transportOn)}else if(key==='z'||key==='x'){keyboardBase=Math.max(24,Math.min(72,keyboardBase+(key==='z'?-12:12)));renderKeyboard()}else if(keyMap[key]!==undefined){e.preventDefault();const b=$(`[data-piano="${keyMap[key]}"]`);b?.classList.add('held');playNote(keyboardBase+keyMap[key],.85,'key-'+key)}});
document.addEventListener('keyup',e=>{const key=e.key.toLowerCase();if(keyMap[key]!==undefined){$(`[data-piano="${keyMap[key]}"]`)?.classList.remove('held');releaseNote('key-'+key)}});
window.addEventListener('blur',()=>{for(const id of [...heldKeys])releaseNote(id);$$('.piano button').forEach(b=>b.classList.remove('held'))});
$('#rootNote').innerHTML=Array.from({length:37},(_,i)=>`<option value="${i+24}">${noteName(i+24)}</option>`).join('');$('#rootNote').onchange=e=>{state.bass.root=+e.target.value;changedBass()};
for(const key of ['subLevel','charLevel'])$('#'+key).oninput=e=>{state.bass[key]=+e.target.value;$('#'+key+'Value').textContent=Math.round(+e.target.value*100)+'%';changedBass()};
$('#layerSolo').onchange=e=>{state.bass.solo=e.target.value;changedBass()};$('#fxBypass').onchange=e=>{state.bass.bypass=e.target.checked;changedBass()};$('#gainMatch').onchange=e=>{state.bass.gainMatch=e.target.checked;changedBass()};$$('[data-bank]').forEach(b=>b.onclick=()=>loadPreset(+b.dataset.bank));
const mutationLocks=document.createElement('div');mutationLocks.className='mutation-locks';mutationLocks.innerHTML='<label><input id="lockSub" type="checkbox">Lock sub during mutation</label><label><input id="lockRhythm" type="checkbox">Lock rhythm during mutation</label>';$('#performance').appendChild(mutationLocks);
for(const key of ['lockSub','lockRhythm'])$('#'+key).onchange=e=>{state.bass[key]=e.target.checked;changedBass()};
$('#random').onclick=()=>{const p=state.bass;state.macros=state.macros.map((v,i)=>((p.lockSub&&i===4)||(p.lockRhythm&&i===1))?v:Math.round(Math.max(0,Math.min(100,v+(Math.random()-.5)*50))));for(const key of ['fm','warp','vowel','midDrive']){const spec=rangeSpec[key];p[key]=Math.max(spec[1],Math.min(spec[2],p[key]+(Math.random()-.5)*(spec[2]-spec[1])*.2));}if(!p.lockRhythm)p.steps=p.steps.map(s=>({...s,on:Math.random()<.15?!s.on:s.on}));if(!p.lockSub)p.subSat=Math.min(1,Math.max(0,p.subSat+(Math.random()-.5)*.3));render();changedBass();toast('Patch mutated · protected layers retained')};
$('#connectMidi').onclick=async()=>{
  if(!navigator.requestMIDIAccess){toast('Web MIDI is unavailable in this browser. Use the on-screen keyboard.');return;}
  try{const access=await navigator.requestMIDIAccess({sysex:false});const attach=()=>{for(const input of access.inputs.values()){input.onmidimessage=({data})=>{const status=data[0]&0xf0,note=data[1],value=data[2],id='midi-'+input.id+'-'+note;if(status===0x90&&value)playNote(note,value/127,id);else if(status===0x80||status===0x90)releaseNote(id);else if(status===0xe0)bassNode?.port.postMessage({type:'bend',value:((value<<7|note)-8192)/8192});else if(status===0xb0&&(note===120||note===123))$('#panic').click()};midiInputs.set(input.id,input)}$('#midiStatus').textContent=access.inputs.size?access.inputs.size+' MIDI INPUT(S)':'NO MIDI INPUT';};attach();access.onstatechange=attach;}catch(e){toast('MIDI access was not available. The on-screen keyboard still works.');}
};
function encodeSample(samples,rate,root){const targetRate=22050,max=Math.min(samples.length,rate*8),length=Math.floor(max*targetRate/rate),bytes=new Uint8Array(length*2),view=new DataView(bytes.buffer);for(let i=0;i<length;i++){const pos=i*rate/targetRate,idx=Math.floor(pos),f=pos-idx,v=(samples[idx]||0)*(1-f)+(samples[Math.min(idx+1,max-1)]||0)*f;view.setInt16(i*2,Math.round(Math.max(-1,Math.min(1,v))*32767),true);}let str='';for(let i=0;i<bytes.length;i+=8192)str+=String.fromCharCode(...bytes.subarray(i,i+8192));return{id:'audio-'+Date.now(),data:btoa(str),rate:targetRate,root,length};}
function decodeSample(sample){const str=atob(sample.data),bytes=new Uint8Array(str.length);for(let i=0;i<str.length;i++)bytes[i]=str.charCodeAt(i);const view=new DataView(bytes.buffer),out=new Float32Array(bytes.length/2);for(let i=0;i<out.length;i++)out[i]=view.getInt16(i*2,true)/32768;return out;}
function storeCaptured(samples,rate,root){state.bass.sample=encodeSample(samples,rate,root);sampleCache=decodeSample(state.bass.sample);state.bass.sampleStart=0;state.bass.sampleEnd=1;sentSampleId=null;$('#captureState').textContent='READY · '+(sampleCache.length/22050).toFixed(2)+' s';drawSample();changedBass();toast('Phrase captured. Raise Resample blend to use it.');}
async function capturePhrase(){try{await ensureAudio();const seconds=Math.min(8,state.bass.captureBars*4*60/state.bpm);$('#captureState').textContent='RECORDING · '+seconds.toFixed(2)+' s';bassNode.port.postMessage({type:'capture',seconds,sub:state.bass.captureSub});if(!transportOn){autoCaptureTransport=true;await setTransport(true)}}catch(e){toast('Capture failed: '+e.message)}}
async function importSample(e){const file=e.target.files[0];if(!file)return;try{await ensureAudio();const decoded=await bassContext.decodeAudioData(await file.arrayBuffer()),mono=new Float32Array(Math.min(decoded.length,decoded.sampleRate*8));for(let c=0;c<decoded.numberOfChannels;c++){const channel=decoded.getChannelData(c);for(let i=0;i<mono.length;i++)mono[i]+=channel[i]/decoded.numberOfChannels;}storeCaptured(mono,decoded.sampleRate,state.bass.root)}catch(e){toast('Could not decode this audio file. Try WAV.')}}
function exportSample(){if(!state.bass.sample)return toast('Capture or import audio first.');const samples=sampleCache||decodeSample(state.bass.sample),rate=state.bass.sample.rate,lo=Math.floor(state.bass.sampleStart*samples.length),hi=Math.max(lo+1,Math.floor(state.bass.sampleEnd*samples.length)),len=hi-lo,buffer=new ArrayBuffer(44+len*2),v=new DataView(buffer);const text=(pos,str)=>{for(let i=0;i<str.length;i++)v.setUint8(pos+i,str.charCodeAt(i))};text(0,'RIFF');v.setUint32(4,36+len*2,true);text(8,'WAVEfmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,rate,true);v.setUint32(28,rate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);text(36,'data');v.setUint32(40,len*2,true);for(let i=0;i<len;i++){const idx=state.bass.sampleReverse?hi-1-i:lo+i;v.setInt16(44+i*2,Math.max(-32767,Math.min(32767,samples[idx]*32767)),true)}const a=document.createElement('a'),url=URL.createObjectURL(new Blob([buffer],{type:'audio/wav'}));a.href=url;a.download='motherbox-capture.wav';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function drawSample(){const c=$('#sampleWave');if(!c)return;const w=c.clientWidth||500,h=90;c.width=w;c.height=h;const ctx=c.getContext('2d');ctx.fillStyle='#102619';ctx.fillRect(0,0,w,h);if(!state.bass.sample){ctx.fillStyle='#7d9d69';ctx.font='10px monospace';ctx.fillText('CAPTURE A PHRASE OR IMPORT AUDIO',15,48);return;}sampleCache=sampleCache||decodeSample(state.bass.sample);const samples=sampleCache;ctx.strokeStyle='#9fbd85';ctx.beginPath();for(let x=0;x<w;x++){let peak=0;const start=Math.floor(x/w*samples.length),end=Math.floor((x+1)/w*samples.length);for(let i=start;i<end;i++)peak=Math.max(peak,Math.abs(samples[i]));ctx.moveTo(x,h/2-peak*h*.45);ctx.lineTo(x,h/2+peak*h*.45)}ctx.stroke();ctx.fillStyle='#070f0bbb';ctx.fillRect(0,0,state.bass.sampleStart*w,h);ctx.fillRect(state.bass.sampleEnd*w,0,w,h);ctx.strokeStyle='#d4b374';for(const x of[state.bass.sampleStart*w,state.bass.sampleEnd*w]){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}}
function analysis(){requestAnimationFrame(analysis);if(++analysisFrame%3)return;const waveCanvas=$('#outputWave'),spectrum=$('#outputSpectrum');for(const c of[waveCanvas,spectrum]){const w=c.clientWidth||400;if(c.width!==w)c.width=w;c.height=80;const ctx=c.getContext('2d');ctx.fillStyle='#102519';ctx.fillRect(0,0,c.width,80);ctx.strokeStyle='#355132';ctx.beginPath();ctx.moveTo(0,40);ctx.lineTo(c.width,40);ctx.stroke()}
  if(!analyser)return;analyser.getFloatTimeDomainData(timeData);analyser.getFloatFrequencyData(frequencyData);analyserSub.getFloatTimeDomainData(subData);leftAnalyser.getFloatTimeDomainData(leftData);rightAnalyser.getFloatTimeDomainData(rightData);
  let ctx=waveCanvas.getContext('2d');ctx.strokeStyle='#b8d394';ctx.beginPath();for(let x=0;x<waveCanvas.width;x++){const y=40-timeData[Math.floor(x/waveCanvas.width*timeData.length)]*35;x?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke();
  ctx=spectrum.getContext('2d');ctx.strokeStyle='#c7ba7c';ctx.beginPath();for(let x=0;x<spectrum.width;x++){const hz=20*Math.pow(1000,x/spectrum.width),idx=Math.min(frequencyData.length-1,Math.round(hz/bassContext.sampleRate*analyser.fftSize)),v=frequencyData[idx],y=80-Math.max(0,Math.min(1,(v+100)/90))*78;x?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke();
  let peak=0,sub=0,cross=0,l2=0,r2=0;for(const v of timeData)peak=Math.max(peak,Math.abs(v));for(let i=0;i<1024;i++){sub+=subData[i]*subData[i];cross+=leftData[i]*rightData[i];l2+=leftData[i]*leftData[i];r2+=rightData[i]*rightData[i];}$('#peakLevel').textContent=peak>1e-5?(20*Math.log10(peak)).toFixed(1)+' dBFS':'—';$('#subMeter').textContent=sub>1e-8?(20*Math.log10(Math.sqrt(sub/1024))).toFixed(1)+' dBFS':'—';$('#correlation').textContent=l2*r2>1e-10?(cross/Math.sqrt(l2*r2)).toFixed(2):'—';if(transportOn)$('#liveNote').textContent=noteName(state.bass.root+(state.bass.steps[latestStatus.step]?.note||0))+' · STEP '+String(latestStatus.step+1).padStart(2,'0');else if(!heldKeys.size)$('#liveNote').textContent='NO NOTE';
}
if(!hadBass){cleanSignature=patchSignature();state.cleanSignature=cleanSignature;}
render();renderKeyboard();requestAnimationFrame(analysis);
